i created a simple workaround:
function unixNow() {
    const d = new Date();
    const y = d.getUTCFullYear();
    const m = d.getUTCMonth();
    const day = d.getUTCDate();
    const daysInMonth = [31, (y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0)) ? 29 : 28,
                         31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let days = 0;
    for (let yr = 1970; yr < y; yr++)
        days += (yr % 4 === 0 && (yr % 100 !== 0 || yr % 400 === 0)) ? 366 : 365;
    for (let i = 0; i < m; i++) days += daysInMonth[i];
    days += day - 1;
    return days * 86400 + d.getUTCHours() * 3600 + d.getUTCMinutes() * 60 + d.getUTCSeconds();
}

