### What steps can reproduce the bug?

Per the [Node docs](https://nodejs.org/api/http.html#serverclosealllconnections), `Server.prototype.closeAllConnections()` should forcefully close every established HTTP(S) connection but **leave the listening socket open** so subsequent connections can still be accepted. Under Bun the listener is also torn down, so the next request gets `ECONNREFUSED`.

```js
// repro.js
const http = require("http");
const server = http.createServer((req, res) => res.end("ok"));
server.listen(0);
server.on("listening", () => {
  const { port } = server.address();
  server.closeAllConnections();
  setTimeout(() => {
    http
      .get(`http://127.0.0.1:${port}/`, r => {
        console.log("status:", r.statusCode);
        server.close();
      })
      .on("error", e => {
        console.log("error:", e.code);
        server.close();
      });
  }, 100);
});
```

