  const port = server.address().port;
  const sock = net.connect(port, "127.0.0.1", () => {
    sock.write(
      "GET / HTTP/1.1\r\n" +
      "Host: x\r\n" +
      "X-Mixed-CASE: alpha\r\n" +
      "x-LOWER-mixed: beta\r\n" +
      "Connection: close\r\n\r\n"
