## Repro

```js
// BUN_FEATURE_FLAG_INTERNAL_FOR_TESTING=1
const c = require("bun:internal-for-testing").cssInternals;
const D = 16;
const css = ".a{--x:" + "rgb(from light-dark(red,blue) r g b/".repeat(D) + "1" + ")".repeat(D) + "}";
