const CAP = 1024 * 1024 * 1024;                   // stop at 1 GiB so we don't OOM the box
let pulls = 0, enqueued = 0;

const server = Bun.serve({
  port: 0,
  fetch() {
    const stream = new ReadableStream({
      async pull(controller) {
        pulls++; controller.enqueue(CHUNK); enqueued += CHUNK.byteLength;
        if (enqueued >= CAP) return controller.close();
        if (pulls % 256 === 0) await new Promise((r) => setTimeout(r, 0)); // yield so the timer can log
      },
    }, { highWaterMark: 1 }); // pull should pause after 1 queued chunk until the consumer drains
    return new Response(stream);
