using server = Bun.serve({
  port: 0, tls, http3: true, http1: false,
  async fetch(req) { return new Response("body:" + (await req.bytes()).length); },
});
const url = `https://127.0.0.1:${server.port}/`;
const h3 = { protocol: "http3", tls: { rejectUnauthorized: false } };

// Comment this warmup out and the next fetch rejects with HTTP3StreamReset.
// await fetch(url, { ...h3, method: "POST", body: "warmup" }).then(r => r.text());

const res = await fetch(url, {
  ...h3, method: "POST", body: "request-content",
