  fs.writeFileSync(path.join(utilsDir, n),
    'const path = require("path");\nmodule.exports = { d: __dirname };\n');
}

const expected = utilsDir;
console.log("ROOT =", ROOT);
for (const n of ["a", "child", "file-io", "index"]) {
  const reqPath = ROOT + "/utils/" + n;   // absolute, forward slash, NO extension
  try { delete require.cache[require.resolve(reqPath)]; } catch (e) {}
  let d; try { d = require(reqPath).d; } catch (e) { d = "ERROR: " + e.message; }
  console.log(("require .../" + n).padEnd(28), "__dirname =", d, d === expected ? "OK" : "WRONG");
}
```

Run with `bun repro.js` vs `node repro.js`.

### What is expected?

The child's `__dirname` equals `...\bun_repro_xxx\utils` for all four — matching Node.js.

### What do you see instead?

Under **bun**, all four produce a wrong `__dirname` with the last segment (`utils`) dropped (`...\Local\Temp` instead of `...\Local\Temp\bun_repro_xxx\utils`). Under **node**, all four are correct.

### Exact trigger conditions (verified)

The bug requires **all three** to hold simultaneously:
1. absolute path (not relative `./`),
2. contains a forward slash `/` (mixed `\`+`/` or all `/`),
3. **no `.js` extension** (relies on auto-resolution).

If the path uses all backslashes, OR includes the `.js` extension, the bug does **not** trigger. Reproduced with ASCII-only paths and CJK paths alike — non-ASCII is not required.

### Real-world impact

A module doing `path.join(__dirname, "..", "prompts")` resolves to a non-existent directory and silently fails file reads. Workaround: `path.join(path.dirname(path.resolve(__filename)), ...)` instead of relying on `__dirname`.

