    let mut sec: f64 = milliseconds.div_euclid(MS_PER_S);
    let mut nsec: f64 = milliseconds.rem_euclid(MS_PER_S) * NS_PER_MS;

    if nsec < 0.0 {
        nsec += NS_PER_S;
        sec -= 1.0;
    }

    libc::timespec {
        tv_sec: sec as _,
        tv_nsec: nsec as _,
    }
}
