import os from 'node:os';
import path from 'node:path';

const t = fs.mkdtempSync(path.join(os.tmpdir(), 'cpsync-'));
const src = path.join(t, 'src'), dst = path.join(t, 'dst');

function reset() {
  fs.rmSync(src, { recursive: true, force: true });
  fs.rmSync(dst, { recursive: true, force: true });
  fs.mkdirSync(src, { recursive: true });
  fs.mkdirSync(dst, { recursive: true });
  fs.writeFileSync(path.join(src, 'f.txt'), 'NEW');
  fs.writeFileSync(path.join(dst, 'f.txt'), 'OLD');
}
const read = () => fs.readFileSync(path.join(dst, 'f.txt'), 'utf8');

reset();
fs.cpSync(src, dst, { recursive: true });
console.log('no filter                    ->', read(), '(expected NEW)');

reset();
fs.cpSync(src, dst, { recursive: true, filter: () => true });
console.log('with filter, force defaulted ->', read(), '(expected NEW)');

reset();
fs.cpSync(src, dst, { recursive: true, force: true, filter: () => true });
console.log('with filter, force explicit  ->', read(), '(expected NEW)');
```

Note the filter is `() => true` — it excludes nothing, so all three calls should behave identically.

