import { tmpdir } from 'node:os';
import { join } from 'node:path';

const FILES = 20;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

for (const spacingMs of [0, 5, 10, 20, 50]) {
  const dir = mkdtempSync(join(tmpdir(), 'watch-burst-'));
  const seen = new Set();
  const watcher = watch(dir, (_event, filename) => {
    if (/^f\d+$/.test(String(filename))) seen.add(String(filename));
  });

  await sleep(400);
  for (let i = 0; i < FILES; i++) {
    writeFileSync(join(dir, `f${i}`), 'x');
    if (spacingMs) await sleep(spacingMs);
  }
  await sleep(1500);

  watcher.close();
  console.log(`spacing ${String(spacingMs).padStart(2)}ms: reported ${seen.size}/${FILES}`);
}
