### What steps can reproduce the bug?

`DatabaseSync.close()` does not appear to finalize outstanding prepared statements, so the underlying SQLite file handle stays open. On Windows the database file is then still locked, and removing its directory fails with `EBUSY`. Node releases it.

The trigger is `db.prepare()` alone — the statement never has to be executed. `exec()` on its own is fine.

```js
import { DatabaseSync } from 'node:sqlite';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

function attempt(label, work) {
  const dir = mkdtempSync(join(tmpdir(), 'nar-'));
  const db = new DatabaseSync(join(dir, 'x.db'));
  try { work(db); } finally { db.close(); }
  try { rmSync(dir, { recursive: true, force: true }); return `${label}: OK`; }
  catch (e) { return `${label}: FAIL ${e.code}`; }
}

console.log(attempt('open+close only          ', () => {}));
console.log(attempt('exec CREATE              ', d => d.exec('CREATE TABLE t (a INTEGER)')));
console.log(attempt('exec CREATE + exec INSERT', d => { d.exec('CREATE TABLE t (a INTEGER)'); d.exec('INSERT INTO t VALUES (1)'); }));
console.log(attempt('prepare, never run       ', d => { d.exec('CREATE TABLE t (a INTEGER)'); d.prepare('INSERT INTO t VALUES (?)'); }));
console.log(attempt('prepare + run            ', d => { d.exec('CREATE TABLE t (a INTEGER)'); d.prepare('INSERT INTO t VALUES (?)').run(1); }));
```

