let received = 0;
dc.subscribe("my:channel", () => { received++; });          // nothing else references the channel
await new Promise((r) => setTimeout(r, 0));
gc(); gc();
await new Promise((r) => setTimeout(r, 50));                 // let finalizers run
dc.channel("my:channel").publish({});
