  const fn = jest.fn();
  fn.mockReturnValueOnce(1)
    .mockReturnValueOnce(2)
    .mockImplementation(() => {
      fn.mockClear();
      return 3;
    });
  fn();
  fn();
  const captured = fn.mock.results; // captured before the call that clears
  fn();
  expect(captured.map(r => r.type)).toEqual(["return", "return", "return"]);
