const b = Buffer.from("abcabc");

// 1. An empty value. Node.js returns the byteOffset, like String#indexOf.
console.log(b.indexOf(""), b.lastIndexOf(""), b.includes(""));

// 2. A Uint8Array value that is not a Buffer.
try {
  console.log(b.indexOf(new Uint8Array([98])));
} catch (e) {
  console.log(e.message);
}

// 3. The `end` argument: indexOf(value, byteOffset, end, encoding).
console.log(b.indexOf("c", 0, 2), b.lastIndexOf("c", undefined, 4));
```

