// sends again, as a client with a retry does.
const dgram = require("node:dgram");

const probe = dgram.createSocket("udp4");
probe.bind(0, "127.0.0.1", () => {
  const port = probe.address().port;
  probe.close(() => {
    const socket = dgram.createSocket("udp4");
    let errors = 0;
    let immediates = 0;
    let timerFired = false;
    socket.on("error", () => {
      if (++errors === 1) {
        setImmediate(() => immediates++);
        setTimeout(() => (timerFired = true), 1);
      }
      if (errors === 100000) {
        console.log(`${errors} 'error' events; setImmediate ran ${immediates} times; the 1 ms timer fired: ${timerFired}`);
        process.exit(1);
      }
      socket.send("retry");
    });
    socket.connect(port, "127.0.0.1", () => {
      socket.send("first");
      let turns = 0;
      (function turn() {
        if (++turns === 200) {
          console.log(`200 loop turns; ${errors} 'error' events; the 1 ms timer fired: ${timerFired}`);
          process.exit(0);
        }
        setImmediate(turn);
      })();
    });
  });
