      t0 = ms();
      setInterval(() => ticks++, 100);
      setTimeout(() => {
        console.log(`timer fired at ${ms() - t0} ms; ${ticks} of 40 ticks; ${events} 'data' events; ${bytes >> 20} MiB`);
