// Let the main thread's clock run for a second before the worker starts.
await new Promise((resolve) => setTimeout(resolve, 1000));

const worker = new Worker(
  `require("node:worker_threads").parentPort.postMessage(String(process.hrtime.bigint()));`,
  { eval: true },
);
const inWorker = BigInt(await new Promise((resolve) => worker.once("message", resolve)));
const inMain = process.hrtime.bigint();
await worker.terminate();

// Both readings were taken within a millisecond or so of each other.
console.log("main - worker (ms):", Number(inMain - inWorker) / 1e6);
