    gc();
    const [key] = Object.getOwnPropertySymbols(object); // still there
    if (!registry.has(key)) entryLost++;
    if (ref.deref() === undefined) refCleared++;
  }
  return `WeakMap entry lost ${entryLost}/${runs}, WeakRef cleared ${refCleared}/${runs}`;
}

