### What happens

A zstd compressor stream that has `ZSTD_c_nbWorkers` gives no output and no error when one chunk is larger than one job.

Node v26.3.0 and v26.10.0 give the same result, so this is not a difference from Node. The stream loses the data without an error in both.

### Reproduction

```js
const zlib = require("node:zlib");
const { finished } = require("node:stream/promises");
const { ZSTD_c_nbWorkers, ZSTD_c_jobSize } = zlib.constants;
const MiB = 1024 * 1024;
const input = Buffer.alloc(MiB, "Lorem ipsum dolor sit amet, consectetur adipiscing elit. ");

async function run(label, params, feed) {
  const stream = zlib.createZstdCompress({ params });
  const chunks = [];
  stream.on("data", chunk => chunks.push(chunk));
  feed(stream);
  await finished(stream);
  const out = Buffer.concat(chunks);
  let roundTrip;
  try {
    roundTrip = zlib.zstdDecompressSync(out).equals(input);
  } catch (e) {
    roundTrip = e.code;
  }
  console.log(label + ":", out.length, "bytes, round trip:", roundTrip);
}

(async () => {
  const workers = { [ZSTD_c_nbWorkers]: 1, [ZSTD_c_jobSize]: MiB / 2 };
  await run("no workers, end(1 MiB)", {}, s => s.end(input));
  await run("1 worker, end(1 MiB)", workers, s => s.end(input));
  await run("1 worker, write(1 MiB) + end()", workers, s => (s.write(input), s.end()));
  await run("1 worker, write(512 KiB) + end(512 KiB)", workers, s => (s.write(input.subarray(0, MiB / 2)), s.end(input.subarray(MiB / 2))));
})();
```

