class Node {
  big = Array.from({ length: 20_000 }, (_, i) => ({ i, label: `item-${i}` }));
  [Symbol.for("nodejs.util.inspect.custom")]() {
    return "<Node>";
  }
}

const len = (fn: () => void) => {
  try { fn(); } catch (e) { return String((e as Error).message).length; }
  return -1;
};

test("failure message lengths", () => {
  const node = new Node();
  const spy = mock((..._args: unknown[]) => {});
  spy(node);
  console.log({
    toBeNull: len(() => expect(node).toBeNull()),
    toBe: len(() => expect(node).toBe(null)),
    toEqual: len(() => expect(node).toEqual(null)),
    toStrictEqual: len(() => expect({ node }).toStrictEqual({ node: null })),
    toMatchObject: len(() => expect({ node }).toMatchObject({ node: null })),
    toHaveBeenCalledWith: len(() => expect(spy).toHaveBeenCalledWith(null)),
  });
});
```

