```ts
import net from "node:net";
import https from "node:https";
import tls from "node:tls";
import { Duplex } from "node:stream";
import { SocksClient } from "socks"; // socks@2

class MeteredTunnel extends Duplex {
  constructor(private raw: net.Socket) {
    super();
    raw.on("data", (c) => { if (!this.push(c)) raw.pause(); });
    raw.on("end", () => this.push(null));
    raw.on("close", () => this.push(null));
    raw.on("error", (e) => this.destroy(e));
  }
  _read() { this.raw.resume(); }
  _write(chunk, _enc, cb) {
    if (this.raw.write(chunk)) cb();
    else this.raw.once("drain", cb);
  }
  _destroy(err, cb) { this.raw.destroy(); cb(err); }
}

const agent = new https.Agent({ keepAlive: true, maxSockets: 13 });
agent.createConnection = ((_opts, cb) => {
  dial().then((s) => cb(null, s), cb);
  return undefined;
}) as typeof agent.createConnection;

async function dial() {
  const { socket: raw } = await SocksClient.createConnection({
    proxy: { host: PROXY_HOST, port: PROXY_PORT, type: 5 },
    command: "connect",
    destination: { host: HOST, port: 443 }, // DNS resolved by the proxy
    timeout: 10_000,
  });
  return tls.connect({
    socket: new MeteredTunnel(raw),
    servername: HOST,
    ALPNProtocols: ["http/1.1"],
  });
}

https.get(
  { host: HOST, path, agent, signal: AbortSignal.timeout(10_000) },
  (res) => { /* read body */ },
);
```

