A server streams an endless response with the usual write-until-`false` / wait-for-`'drain'` loop; the client destroys its session after the first chunk.

```js
import http2 from "node:http2";

const chunk = Buffer.alloc(64 * 1024);
const server = http2.createServer();
server.on("stream", (stream) => {
  stream.on("error", () => {});
  stream.on("drain", () => console.log("drain, destroyed:", stream.destroyed));
  stream.on("close", () => {
    console.log("server stream closed");
    server.close();
  });
  stream.respond({ ":status": 200 });
  let writes = 0;
  const pump = () => {
    while (!stream.destroyed && stream.write(chunk)) {
      if (++writes === 1000) {
        console.log("write() returned true 1000 times after the client left");
        process.exit(1);
      }
    }
    if (!stream.destroyed) stream.once("drain", pump);
  };
  pump();
});
server.listen(0, "127.0.0.1", () => {
  const client = http2.connect(`http://127.0.0.1:${server.address().port}`);
  client.on("error", () => {});
  const req = client.request({ ":path": "/" });
  req.on("error", () => {});
  req.once("data", () => client.destroy());
});
